PartPOneVoiceOne = \relative a' {
  \clef "treble" \time 6/4 \key c \major \parenthesize a4 \tweak style #'cross
  \parenthesize a4 <a \parenthesize c e>4 <\parenthesize a \parenthesize c
    \parenthesize e>4 r4 e4\rest \bar "|."
}


